const UNITS = { h: 3600000, m: 60000, s: 1000, ms: 1 };

export function parseDuration(text) {
  if (typeof text !== 'string' || text.length === 0) {
    throw new Error(`bad duration: ${text}`);
  }
  let total = 0;
  let i = 0;
  while (i < text.length) {
    let j = i;
    while (j < text.length && /\d/.test(text[j])) j++;
    if (j === i) throw new Error(`bad duration: ${text}`);
    const num = Number(text.slice(i, j));
    let unit = null;
    for (const u of ['ms', 'h', 'm', 's']) {
      if (text.startsWith(u, j)) {
        unit = u;
        break;
      }
    }
    if (!unit) throw new Error(`bad duration: ${text}`);
    total += num * UNITS[unit];
    i = j + unit.length;
  }
  return total;
}

