const ROMAN_MAP = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
];

const ROMAN_VALUES = new Map([
  ['M', 1000], ['CM', 900], ['D', 500], ['CD', 400],
  ['C', 100], ['XC', 90], ['L', 50], ['XL', 40],
  ['X', 10], ['IX', 9], ['V', 5], ['IV', 4], ['I', 1],
]);

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('out of range');
  }
  let result = '';
  let remaining = n;
  for (const [value, symbol] of ROMAN_MAP) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string' || s.length === 0) {
    throw new Error('invalid input');
  }

  let total = 0;
  let i = 0;
  while (i < s.length) {
    const twoChar = s.slice(i, i + 2);
    if (ROMAN_VALUES.has(twoChar)) {
      total += ROMAN_VALUES.get(twoChar);
      i += 2;
    } else {
      const oneChar = s[i];
      if (!ROMAN_VALUES.has(oneChar)) {
        throw new Error('invalid input');
      }
      total += ROMAN_VALUES.get(oneChar);
      i += 1;
    }
  }

  // Validation: re-convert to ensure no malformed input like IIII or VIV
  if (toRoman(total) !== s) {
    throw new Error('invalid input');
  }

  return total;
}

