const ROMAN_MAP = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
];

const ROMAN_VALUES = {
  I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000
};

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999');
  }

  let result = '';
  for (const [value, symbol] of ROMAN_MAP) {
    while (n >= value) {
      result += symbol;
      n -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string' || s.length === 0) {
    throw new Error('Invalid Roman numeral');
  }

  let total = 0;
  let i = 0;
  while (i < s.length) {
    const current = ROMAN_VALUES[s[i]];
    if (current === undefined) {
      throw new Error('Invalid Roman numeral');
    }

    if (i + 1 < s.length) {
      const next = ROMAN_VALUES[s[i + 1]];
      if (next === undefined) {
        throw new Error('Invalid Roman numeral');
      }

      if (next > current) {
        // Check for valid subtractive pairs
        const pair = s[i] + s[i + 1];
        const validPairs = ['IV', 'IX', 'XL', 'XC', 'CD', 'CM'];
        if (!validPairs.includes(pair)) {
          throw new Error('Invalid Roman numeral');
        }
        total += next - current;
        i += 2;
        continue;
      }
    }

    total += current;
    i += 1;
  }

  if (total < 1 || total > 3999) {
    throw new Error('Invalid Roman numeral');
  }

  // Verify round-trip to catch non-canonical forms like "IIII", "VX", etc.
  if (toRoman(total) !== s) {
    throw new Error('Invalid Roman numeral');
  }

  return total;
}

