const fs = require('fs');
const path = require('path');

const srcDir = 'src';
const allFiles = [];

function collectFiles(dir) {
  for (const entry of fs.readdirSync(dir)) {
    const fullPath = path.join(dir, entry);
    const stat = fs.statSync(fullPath);
    if (stat.isDirectory()) {
      collectFiles(fullPath);
    } else if (entry.endsWith('.js')) {
      allFiles.push(fullPath);
    }
  }
}
collectFiles(srcDir);

// Find all exported function definitions
const functionDefs = new Map(); // name -> file
const functionDefRegex = /export\s+(?:async\s+)?function\s+(\w+)/g;
const functionDefRegex2 = /export\s+const\s+(\w+)\s*=\s*(?:async\s+)?\(/g;

for (const file of allFiles) {
  const content = fs.readFileSync(file, 'utf8');
  let m;
  while ((m = functionDefRegex.exec(content)) !== null) {
    functionDefs.set(m[1], file);
  }
  while ((m = functionDefRegex2.exec(content)) !== null) {
    functionDefs.set(m[1], file);
  }
}

console.log('Functions defined in src/:');
for (const [name, file] of functionDefs) {
  console.log(`  ${name} in ${file}`);
}

// Count call sites across all src/ files (excluding comments)
function stripComments(code) {
  // Remove single-line comments
  let result = code.replace(/\/\/.*$/gm, '');
  // Remove multi-line comments
  result = result.replace(/\/\*[\s\S]*?\*\//g, '');
  return result;
}

const callCounts = new Map();
for (const name of functionDefs.keys()) {
  callCounts.set(name, new Set()); // Set of files where called
}

for (const file of allFiles) {
  const content = fs.readFileSync(file, 'utf8');
  const codeOnly = stripComments(content);

  for (const name of functionDefs.keys()) {
    // Match function calls like: name( or name(
    const regex = new RegExp(`\\b${name}\\s*\\(`, 'g');
    const matches = codeOnly.match(regex);
    if (matches && matches.length > 0) {
      // Don't count the definition itself
      const isDefFile = functionDefs.get(name) === file;
      if (isDefFile) {
        // Check if there are calls beyond the definition
        // Simple approach: count all matches, subtract 1 for definition
        // But only if the definition line contains the function name
        const defMatch = content.match(new RegExp(`export\\s+(?:async\\s+)?function\\s+${name}\\s*\\(`));
        if (defMatch) {
          callCounts.get(name).add(file);
        } else {
          callCounts.get(name).add(file);
        }
      } else {
        callCounts.get(name).add(file);
      }
    }
  }
}

// More precise: count actual call occurrences excluding definition line
const preciseCounts = new Map();
for (const name of functionDefs.keys()) {
  preciseCounts.set(name, 0);
}

for (const file of allFiles) {
  const lines = fs.readFileSync(file, 'utf8').split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    // Skip comment-only lines
    const stripped = line.replace(/\/\/.*$/, '').trim();
    if (stripped === '') continue;

    for (const name of functionDefs.keys()) {
      const regex = new RegExp(`\\b${name}\\s*\\(`, 'g');
      const matches = stripped.match(regex);
      if (matches) {
        const isDefLine = stripped.includes(`function ${name}`) || stripped.includes(`const ${name} =`);
        if (!isDefLine) {
          preciseCounts.set(name, preciseCounts.get(name) + matches.length);
        }
      }
    }
  }
}

console.log('\nCall counts (excluding definitions):');
const sorted = [...preciseCounts.entries()].sort((a, b) => b[1] - a[1]);
for (const [name, count] of sorted) {
  console.log(`  ${name}: ${count} calls`);
}

