        else:
            new_data[key] = value

    # If retry was missing, add default
    if 'retry' not in new_data:
        new_data['retry'] = {'attempts': 0, 'backoff_s': 0.0}

    # Ensure key order matches typical expectation: version, name, timeout_s, retry, owners, then others
    # But spec says "Every other key is kept as it is" - so preserve order of non-migrated keys
    ordered = {}
