        # just append before owners if owners exists? Actually, let's insert in a sensible place.
        # The spec doesn't require a specific order, but preserving original order of keys is nice.
        # Since retry wasn't present originally, we need to add it. Let's add it after timeout_s if present,
        # otherwise before owners if present, else at end.
        keys = list(ordered.keys())
        if 'timeout_s' in keys:
            idx = keys.index('timeout_s') + 1
        elif 'owners' in keys:
            idx = keys.index('owners')
        else:
            idx = len(keys)
        items = list(ordered.items())
        items.insert(idx, ('retry', {'attempts': 0, 'backoff_s': 0.0}))
        ordered = dict(items)

