    if data.get('version') == 2:
        print(f"Skipping (already v2): {filepath}")
        continue

    # Build new data preserving order
    new_data = {}
    for key, value in data.items():
        if key == 'version':
            new_data['version'] = 2
        elif key == 'timeoutMs':
            new_data['timeout_s'] = value / 1000.0
        elif key == 'retry':
            new_retry = {}
            for rkey, rvalue in value.items():
                if rkey == 'count':
                    new_retry['attempts'] = rvalue
                elif rkey == 'backoffMs':
                    new_retry['backoff_s'] = rvalue / 1000.0
                else:
                    new_retry[rkey] = rvalue
            new_data['retry'] = new_retry
        elif key == 'owners':
            if isinstance(value, str):
                emails = [e.strip().lower() for e in value.split(',')]
                emails = [e for e in emails if e]
                new_data['owners'] = emails
            else:
                new_data['owners'] = value
        else:
